478	// wwwAuthenticateRealm returns the realm of a Bearer challenge.
479	func wwwAuthenticateRealm(t *testing.T, challenge string) *url.URL {
480		t.Helper()
481		rest, ok := strings.CutPrefix(challenge, "Bearer ")
482		if !ok {
483			t.Fatalf("challenge %q is not a Bearer one", challenge)
484		}
485		realm, ok := parseBearerChallenge(rest)["realm"]
486		if !ok {
487			t.Fatalf("challenge %q names no realm", challenge)
488		}
489		u, err := url.Parse(realm)
490		if err != nil {
491			t.Fatalf("realm %q: %v", realm, err)
492		}
493		return u
494	}
495	
496	// Where the realm points. Measured on the bench, every Bearer challenge names a realm
497	// on the registry's own origin (same scheme and host:port as the request), by the
498	// path of the connector or of the repository, and the client accepts it.
499	//
500	// The X-Forwarded-Host and X-Forwarded-Proto probe shows that Nexus builds the
501	// realm from the host the request ANNOUNCES: behind a reverse proxy that sets them
502	// (the enterprise case, which the bench does not reproduce) the realm is on
503	// whatever origin the proxy says. The probe's answer is replayed here, and what
504	// DevDesk does with such a realm is the fact pinned: it FOLLOWS it. checkTokenRealm
505	// refuses a realm by scheme only (not http behind https, not a scheme other than
506	// http or https); a realm on another origin over https is taken (Docker Hub's own
507	// case, deliberate), and, when credentials are set, they go to it as Basic.
508	//
509	// That contradicts criterion 3 of NX-08b ("the realms off the origin are refused as
510	// measured"): nothing measured shows a refusal, and the code has none. The
511	// contradiction is pinned, not corrected (docs/measurements/2026-11-20-nexus-access.md).
512	func TestMeasuredRealmStaysOnTheRegistryOrigin(t *testing.T) {
513		t.Run("every measured realm is on the origin of its request", func(t *testing.T) {
514			cases := []struct {
515				fixture string
516				host    string
517				target  string
518			}{
519				{"bearer-ping-30481--anon", nxPathHost, "/v2/"},
520				{"bearer-ping-30482--anon", nxConnectorHost, "/v2/"},
521				{"redirects-v2-no-slash-30481--anon", nxPathHost, "/v2"},
522				{"w5-ping-30481--anon", nxPathHost, "/v2/"},
523				{"w5-ping-30482--anon", nxConnectorHost, "/v2/"},
524				{"w6-ping-30481--anon", nxPathHost, "/v2/"},
525				{"w6-ping-30482--anon", nxConnectorHost, "/v2/"},
526				{"w6-catalog-group-connector-30482--anon", nxConnectorHost, "/v2/_catalog?n=1000"},
527				{"w6-catalog-hosted-path--anon", nxPathHost, "/v2/docker-hosted/_catalog?n=1000"},
528			}
529			for _, tc := range cases {
530				t.Run(tc.fixture, func(t *testing.T) {
531					f := nxPick(t, "access", tc.fixture)[0]
532					ex := nxWant(t, f, 0, "GET", tc.target, 401)
533					recorded := wwwAuthenticateRealm(t, ex.Header.Get("Www-Authenticate"))
534					if recorded.Scheme != "http" || recorded.Host != tc.host {
535						t.Fatalf("%s: realm %s, want it on http://%s: the measurement changed", f.Name, recorded, tc.host)
536					}
537					s := fakenexus.New(t, f)
538					useNxWire(t, nil)
539					base := s.URL(tc.host)
540	
541					resp, err := doRequestContext(context.Background(), http.MethodGet, base+tc.target, "", "", "", "")
542					if err != nil {
543						t.Fatal(err)
544					}
545					_ = resp.Body.Close()
546	
547					challenge := resp.Header.Get("Www-Authenticate")
548					realm := wwwAuthenticateRealm(t, challenge)
549					if want := strings.TrimPrefix(base, "http://"); realm.Scheme != "http" || realm.Host != want {
550						t.Errorf("replayed realm = %s, want it on the origin of the request (http://%s)", realm, want)
551					}
552					if err := checkTokenRealm(base, challenge[len("Bearer "):]); err != nil {
553						t.Errorf("checkTokenRealm refuses the measured realm: %v", err)
554					}
555				})
556			}
557		})
558	
559		t.Run("a realm announced off the origin is followed", func(t *testing.T) {
560			const offOrigin = "realm-probe.invalid"
561			cases := []struct {
562				fixture   string
563				host      string
564				tokenPath string
565			}{
566				{"realm-probe-ping-30481--anon", nxPathHost, "/repository/docker-hosted/v2/token"},
567				{"realm-probe-ping-30482--anon", nxConnectorHost, "/v2/token"},
568			}
569			for _, tc := range cases {
570				f := nxPick(t, "access", tc.fixture)[0]
