572				if got := ex.RequestHeader.Get("X-Forwarded-Host"); got != offOrigin {
573					t.Fatalf("%s: X-Forwarded-Host = %q: the probe changed", f.Name, got)
574				}
575				realm := wwwAuthenticateRealm(t, ex.Header.Get("Www-Authenticate"))
576				if realm.Scheme != "https" || realm.Host != offOrigin || realm.Path != tc.tokenPath {
577					t.Fatalf("%s: realm %s, want https://%s%s: the measurement changed", f.Name, realm, offOrigin, tc.tokenPath)
578				}
579	
580				// What answers at the off-origin realm is the test's own stand-in (no network
581				// is touched): a 403, so that the flow ends there.
582				deny := func(*http.Request) *http.Response {
583					return &http.Response{StatusCode: http.StatusForbidden, Header: http.Header{}, Body: io.NopCloser(strings.NewReader(""))}
584				}
585				intercept := map[string]func(*http.Request) *http.Response{offOrigin: deny}
586	
587				t.Run(tc.fixture+", anonymous", func(t *testing.T) {
588					s := fakenexus.New(t, f)
589					wire := useNxWire(t, intercept)
590	
591					_, _, _, err := registryGETContext(context.Background(), s.URL(tc.host)+"/v2/", "", "", "")
592	
593					var se *StatusError
594					if !errors.As(err, &se) || se.Source != SourceToken || se.Code != 403 {
595						t.Fatalf("err = %v (%T), want the 403 of the off-origin token endpoint: the client went there", err, err)
596					}
