599						t.Fatalf("wire = %+v, want the read then ONE token request to %s, with no credentials", reqs, offOrigin)
600					}
601					tokenReq, _ := url.Parse(reqs[1].URI)
602					if tokenReq.Path != tc.tokenPath || tokenReq.Query().Get("service") != realm.String() {
603						t.Errorf("token request = %s, want the realm's path %s and its service %s", reqs[1].URI, tc.tokenPath, realm)
604					}
605					nxHits(t, s, map[string]int{f.Name: 1})
606				})
607	
608				// The credentials of a configured registry: the client sends Basic at once (to
609				// the registry, as Nexus accepts it), and, on the challenge, again to the realm.
610				// The fixture is the probe's anonymous recording, so the registry here is a
611				// handler that serves its recorded 401 to ANY caller: it is the only place this
612				// pin is not a measured exchange, only the measured header.
613				t.Run(tc.fixture+", with credentials", func(t *testing.T) {
614					reg := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
615						for name, values := range ex.Header {
616							for _, v := range values {
617								w.Header().Add(name, v)
618							}
619						}
620						w.WriteHeader(ex.Status)
621						_, _ = w.Write(ex.Body)
622					}))
623					t.Cleanup(reg.Close)
624					wire := useNxWire(t, intercept)
