626					_, _, _, err := registryGETContext(context.Background(), reg.URL+"/v2/", "admin", "S3CRETPW", "")
627	
628					var se *StatusError
629					if !errors.As(err, &se) || se.Source != SourceToken || se.Code != 403 {
630						t.Fatalf("err = %v (%T), want the 403 of the off-origin token endpoint", err, err)
631					}
632					reqs := wire.requests()
633					if len(reqs) != 2 || reqs[1].Host != offOrigin {
634						t.Fatalf("wire = %+v, want the read then one token request to %s", reqs, offOrigin)
635					}
636					if !strings.HasPrefix(reqs[1].Auth, "Basic ") {
637						t.Errorf("Authorization of the token request = %q: the credentials stopped at the registry, this pin is out of date", reqs[1].Auth)
638					}
639				})
